def min_extra_char(s: str, dictionary: list) -> int:
    word_set = set(dictionary)
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(n - 1, -1, -1):
        # Option 1: skip current character (count as extra)
        dp[i] = 1 + dp[i + 1]

        # Option 2: try to match any word starting at i
        for j in range(i + 1, n + 1):
            if s[i:j] in word_set:
                dp[i] = min(dp[i], dp[j])

    return dp[0]

