import sys

MOD = 998244353

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # dp[i][j] = number of ways to process first i characters with balance j
    # balance: number of '(' minus number of ')'
    # We only need balances from 0 to n (cannot exceed n)
    dp = [0] * (n + 2)
    dp[0] = 1

    for i, ch in enumerate(s):
        new_dp = [0] * (n + 2)
        for bal in range(n + 1):
            if dp[bal] == 0:
                continue
            if ch == '(':
                if bal + 1 <= n:
                    new_dp[bal + 1] = (new_dp[bal + 1] + dp[bal]) % MOD
            elif ch == ')':
                if bal - 1 >= 0:
                    new_dp[bal - 1] = (new_dp[bal - 1] + dp[bal]) % MOD
            else:  # ch == '?'
                # Try '('
                if bal + 1 <= n:
                    new_dp[bal + 1] = (new_dp[bal + 1] + dp[bal]) % MOD
                # Try ')'
                if bal - 1 >= 0:
                    new_dp[bal - 1] = (new_dp[bal - 1] + dp[bal]) % MOD
        dp = new_dp

    print(dp[0] % MOD)

