import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    idx = 0
    n = int(input_data[idx])
    idx += 1
    nums = []
    for _ in range(n):
        nums.append(int(input_data[idx]))
        idx += 1
    k = int(input_data[idx])

    # dp[i][j] = max length of a good subsequence ending at index i with exactly j changes
    # We can optimize space by using a dictionary for each j, but given constraints (n<=500, k<=25),
    # a 2D array is fine.

    # Initialize dp table: dp[i][j] = max length ending at i with j changes
    # We'll use -1 to indicate unreachable states
    dp = [[-1] * (k + 1) for _ in range(n)]

    # Base case: each single element subsequence has 0 changes and length 1
    for i in range(n):
        dp[i][0] = 1

    # Fill DP table
    for i in range(1, n):
        for j in range(k + 1):
            # Option 1: Start a new subsequence at i (length 1, 0 changes)
            if j == 0:
                dp[i][j] = max(dp[i][j], 1)

            # Option 2: Extend a previous subsequence ending at p < i
            for p in range(i):
                changes_needed = 0 if nums[p] == nums[i] else 1
                prev_j = j - changes_needed
                if prev_j < 0:
                    continue
                if dp[p][prev_j] == -1:
                    continue

                new_len = dp[p][prev_j] + 1
                if new_len > dp[i][j]:
                    dp[i][j] = new_len

    # Find the maximum length across all ending positions and all allowed changes
    ans = 0
    for i in range(n):
        for j in range(k + 1):
            if dp[i][j] > ans:
                ans = dp[i][j]

    print(ans)

if __name__ == "__main__":
    solve()
