    stand_masks = []
    for s in S:
        mask = 0
        for j, ch in enumerate(s):
            if ch == 'o':
                mask |= (1 << j)
        stand_masks.append(mask)

    target_mask = (1 << M) - 1

    # Try all subsets of stands from size 1 to N
    for k in range(1, N + 1):
        for combo in combinations(range(N), k):
            combined_mask = 0
            for idx in combo:
                combined_mask |= stand_masks[idx]
            if combined_mask == target_mask:
                print(k)
                return

